SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'filterstufen', 'Filterstufen (Typ × Anlagengröße × Kanalsystem → Grenzwerte Tab. 3–14)', 'json', NULL, false, '§4.2.6, §4.3, §4.4, Tab. 3–18', 'Plan 3: Zeilen je Filterstufe (Rolle, Filtertyp, Anlagengröße, Kanalsystem, Fläche, Belastungswerte); Grenzwerte je Zeile aus TABLE_LIMITS; Σ Hauptstufenflächen → A_Fo_gesamt (A262-10-D1), Anzahl Zeilen unter EZ·A_spez → filterstufen_area_fail (A262-10-D2); die 13 Filtertyp-Arbeitsblätter bleiben bestehen (Ablösung Phase 6).', 'imported_unverified', 'Sizing is based on the specific area, as measured on the upper surface of the filter, and the permissible hydraulic load (the larger of the two values determines the design), and differs depending on the type of sewer network (separated or combined). The requirements are given in Table 3. — The specific hydraulic loading requirements of Section 4.3.3 must be verified. Downstream filter areas may not be considered. — Table 17 summarizes the main design parameters for planted and unplanted filters used in small wastewater treatment systems. — Table 18 summarizes the main design parameters for planted and unplanted filters used in municipal wastewater treatment plants.', 'register', '{"title":"Filterstufen","subtitle":"§4.3 — je Filterstufe Typ, Fläche und Tabellengrenzwerte (Tab. 3–16, 17, 18)","add_label":"+ Filterstufe","placement":"section","columns":[{"key":"label","label":"Stufe","type":"text","required":true},{"key":"stage_role","label":"Rolle","type":"enum","required":true,"options":["primary","main","polishing"],"option_labels":{"primary":"Vorbehandlung (Rohabwasserfilter)","main":"biologische Hauptstufe","polishing":"Nachreinigung"}},{"key":"filter_type","label":"Filtertyp","type":"enum","required":true,"options":["vf_sand_0_2","two_stage_vf_gravel_sand","vf_coarse_sand_0_4","aerated_vf_gravel_8_16","vf_lava_sand_0_4","two_layer_filter_trench","aerated_hf_gravel_8_16","hf_coarse_sand_or_gravel_downstream","raw_wastewater_filter"],"option_labels":{"vf_sand_0_2":"VF Sand 0-2 mm","two_stage_vf_gravel_sand":"Zweistufiger VF Feinkies+Grobsand","vf_coarse_sand_0_4":"VF Grobsand 0-4 mm","aerated_vf_gravel_8_16":"Aktiv belüfteter VF Kies 8-16 mm","vf_lava_sand_0_4":"VF Lavasand 0-4 mm","two_layer_filter_trench":"Zweischicht-Filtergraben","aerated_hf_gravel_8_16":"Aktiv belüfteter HF Kies 8-16 mm","hf_coarse_sand_or_gravel_downstream":"HF Grobsand/Feinkies (nachgeschaltet)","raw_wastewater_filter":"Rohabwasser-Filter"},"discriminator":true},{"key":"system_size","label":"Anlagengröße","type":"enum","required":true,"options":["small_wwts","municipal_wwtp"],"option_labels":{"small_wwts":"Kleinkläranlage (≤50 PE)","municipal_wwtp":"Kommunale Kläranlage (>50 PE)"}},{"key":"sewer","label":"Kanalsystem","type":"enum","required":true,"options":["separate_sewer","combined_sewer","no_sewer"],"option_labels":{"separate_sewer":"Trennsystem","combined_sewer":"Mischsystem","no_sewer":"Keine Kanalisation"}},{"key":"sewer_key","label":"Tab.-Spalte","type":"derived","expr":"if(sewer == ''combined_sewer'', ''m'', ''tr'')","display":"badge","value_labels":{"tr":"Tr (separated)","m":"M (combined)"}},{"key":"cells","label":"Anzahl Teilflächen","type":"number","min":1},{"key":"area_m2","label":"Filterfläche A_F","type":"number","unit":"m²","required":true,"min":0,"aria_label":"Filterfläche A_F"},{"key":"a_spez_min","label":"A_spez,min (Tab.)","type":"derived","expr":"lookup(''TABLE_LIMITS'', filter_type, system_size, sewer_key, ''a_spez_min'')"},{"key":"a_min_m2","label":"A_min = EZ·A_spez","type":"derived","expr":"a_spez_min * EZ"},{"key":"a_abs_min_m2","label":"A_min (Tab., absolut)","type":"derived","expr":"lookup(''TABLE_LIMITS'', filter_type, system_size, sewer_key, ''a_min_m2'')"},{"key":"area_ok","label":"A_F ≥ EZ·A_spez","type":"derived","expr":"if(area_m2 >= a_min_m2, 1, 0)","display":"badge","value_labels":{"0":"unterschritten","1":"erfüllt"}},{"key":"f_a_f_csb","label":"f_A,F,CSB","type":"number","unit":"g/(m²·d)","min":0},{"key":"f_a_f_csb_max","label":"max (Tab.)","type":"derived","expr":"lookup(''TABLE_LIMITS'', filter_type, system_size, sewer_key, ''f_a_f_csb_max'')"},{"key":"q_f_t","label":"q_F,T","type":"number","unit":"l/(m²·d)","min":0},{"key":"q_f_t_max","label":"max (Tab.)","type":"derived","expr":"lookup(''TABLE_LIMITS'', filter_type, system_size, sewer_key, ''q_f_t_max'')"},{"key":"q_beschickung","label":"q_Beschickung","type":"number","unit":"l/(m²·min)","min":0},{"key":"q_beschickung_min","label":"min (Tab.)","type":"derived","expr":"lookup(''TABLE_LIMITS'', filter_type, system_size, sewer_key, ''q_beschickung_min'')"},{"key":"h_beschickung","label":"h_Beschickung","type":"number","unit":"l/m²","min":0},{"key":"h_beschickung_min","label":"min (Tab.)","type":"derived","expr":"lookup(''TABLE_LIMITS'', filter_type, system_size, sewer_key, ''h_beschickung_min'')"},{"key":"t_sicker_h","label":"t_Sicker,min,aM","type":"number","unit":"h","min":0,"visible_when":"system_size == ''municipal_wwtp''"},{"key":"t_sicker_min","label":"min (Tab.)","type":"derived","expr":"lookup(''TABLE_LIMITS'', filter_type, system_size, sewer_key, ''t_sicker_min'')","visible_when":"system_size == ''municipal_wwtp''"},{"key":"l_rieselr_m","label":"Σ L_Rieselr","type":"number","unit":"m","min":0,"visible_when":"filter_type == ''two_layer_filter_trench''"},{"key":"a_awf_m2","label":"A_AWF (Abschlagfilter)","type":"number","unit":"m²","min":0,"visible_when":"filter_type == ''vf_lava_sand_0_4'' AND sewer == ''combined_sewer''"}],"footer":["A_Fo_gesamt","filterstufen_area_fail"],"note":"The specific hydraulic loading requirements of Section 4.3.3 must be verified. Downstream filter areas may not be considered."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'filterstufen') AND w.code = 'A262-10' AND s.code = 'DWA-A-262E';
