SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'rieselrohre', 'Rieselrohre des Filtergrabens (Tab. 8)', 'json', NULL, false, '§4.3.1.6, Tab. 8', 'Plan 3: Zeilen je Rieselrohr (Länge, Sohlenbreite); Σ Länge → L_Rieselr_sum (A262-15-D1), längstes Rohr → rieselrohr_max_len (A262-15-D2); Gates Σ L ≥ 6 m/P · EZ und max ≤ 18 m STAGED (a262e-G-10).', 'imported_unverified', '\hline Specific length of infiltration pipe & $l_{\text {Rieselr }}$ & m/P & $\geq 6$ \\ \hline Length of each infiltration pipe & $L_{\text {Rieselr }}$ & m & $\leq 18$ \\', 'register', '{"title":"Rieselrohre","subtitle":"§4.3.1.6 Tab. 8 — je Rieselrohr Länge (≤ 18 m) und Grabensohlenbreite","add_label":"+ Rieselrohr","placement":"section","columns":[{"key":"label","label":"Bezeichnung","type":"text"},{"key":"length_m","label":"L_Rieselr","type":"number","unit":"m","required":true,"min":0,"aria_label":"Länge des Rieselrohrs"},{"key":"width_m","label":"B_FGR","type":"number","unit":"m","min":0,"aria_label":"Breite der Grabensohle je Rieselrohr"}],"footer":["L_Rieselr_sum","rieselrohr_max_len"]}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'rieselrohre') AND w.code = 'A262-15' AND s.code = 'DWA-A-262E';
