SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'L_Rieselr_sum', 'Σ Rieselrohrlänge (Tab. 8: l_Rieselr ≥ 6 m/P)', 'number', 'm', false, '§4.3.1.6, Tab. 8', 'Plan 3: Ausgabe der Gleichung A262-15-D1 (sum_rows über rieselrohre).', 'imported_unverified', '\hline Specific length of infiltration pipe & $l_{\text {Rieselr }}$ & m/P & $\geq 6$ \\', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
