SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'grauwasser_quelle', 'Quelle der Grauwasser-Frachten (Tab. 2: Median / Mittelwert)', 'enum', NULL, false, '§4.1.3, Tab. 2', 'Plan 3: Treiber der Tab.-2-Zeile für B_CSB_Grauwasser (informativ, freie Wahl zwischen den beiden gedruckten Spalten).', 'imported_unverified', 'Table 2 gives informative specific loads for greywater. — \hline Parameter & Greywater Median (from Standard DWA-A 272:2014) & Greywater Average (from Sievers et al. 2:2014) \\', 'select_one', NULL, NULL, NULL, '[{"value":"median","label_de":"Greywater Median (from Standard DWA-A 272:2014)","order_index":0},{"value":"average","label_de":"Greywater Average (from Sievers et al. 2:2014)","order_index":1}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
