UPDATE fields f SET widget = 'lookup_fill', ui_config = '{"source_label":"Tab. 2"}'::jsonb, lookup = '{"table_code":"TABLE2_CSB","role":"value","keys":[{"column":"source","from_symbol":"grauwasser_quelle"}],"value":"load_g_pd"}'::jsonb, visible_when = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'B_CSB_Grauwasser' AND w.code = 'A262-26' AND s.code = 'DWA-A-262E' AND f.active;
