SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'hf_material', 'Filtermaterial des nachgeschalteten Horizontalfilters (Tab. 16)', 'enum', NULL, false, '§4.3.6.2, Tab. 16', 'Plan 3: Treiber der Tab.-16-Zeile (Grobsand ≤ 40 / Kies ≤ 200 g/(m²·d) auf den Anströmquerschnitt).', 'imported_unverified', '\subsection*{4.3.6.2 Horizontal Filter with Coarse Sand 0 mm to 4 mm or Gravel 2 mm to 8 mm} — Horizontal filters without active aeration can be used as an additional biological treatment step. They are operated with permanent saturation and must be designed according to the allowable mass and hydraulic loads. The requirements are provided in Table 16:', 'select_one', NULL, NULL, NULL, '[{"value":"coarse_sand","label_de":"coarse sand (0 mm to 4 mm)","order_index":0},{"value":"gravel","label_de":"gravel (2 mm to 8 mm)","order_index":1}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'hf_material') AND w.code = 'A262-27' AND s.code = 'DWA-A-262E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'f_A_ANF_CSB_max', 'Zulässige CSB-Flächenbelastung des Anströmquerschnitts f_A,ANF,CSB (Tab. 16)', 'number', 'g/(m²·d)', false, '§4.3.6.2, Tab. 16', 'Plan 3: Grenzwert aus TABLE16 zum gewählten Material; das Gate f_A_ANF_CSB ≤ f_A_ANF_CSB_max (ersetzt REQ-91 ≤ 200 auf A262-16) ist STAGED (a262e-G-2).', 'imported_unverified', '\hline Average specific daily CSB (COD) loading rate on the horizontal cross-section when the filter material is coarse sand & $f_{\text {A,ANF, CSB }}$ & $\mathrm{g} /\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ & $\leq 40$ \\ \hline Average specific daily CSB (COD) loading rate on the horizontal cross-section when the filter material is gravel & $f_{\mathrm{A}, \mathrm{ANF}, \mathrm{CSB}}$ & $\mathrm{g} /\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ & $\leq 200$ \\', 'lookup_fill', '{"source_label":"Tab. 16"}'::jsonb, '{"table_code":"TABLE16","role":"limit","keys":[{"column":"material","from_symbol":"hf_material"}],"value":"f_a_anf_csb_max"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'f_A_ANF_CSB_max') AND w.code = 'A262-27' AND s.code = 'DWA-A-262E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'polishing_temp_band', 'Ablauftemperaturband für VF Sand 0–2 mm als Nachreinigungsstufe (Tab. 15)', 'enum', NULL, false, '§4.3.6.1, Tab. 15', 'Plan 3: Treiber der Tab.-15-Zeile (< 12 °C / ≥ 12 °C) für q_Fo,T und t_Sicker,min,aM; Ablösung durch effluent_temperature_C (A262-08) STAGED (a262e-C-5).', 'imported_unverified', 'For determination of the required filter area, the upper surface of the filter is used. The requirements are provided in Table 15: — & $q_{F o, T}$ & $<12^{\circ} \mathrm{C} \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ & $\leq 80$ \\ \hline & $q_{F o, T}$ & $\geq 12^{\circ} \mathrm{C} \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ & $\leq 120^{*}$ \\', 'select_one', NULL, NULL, NULL, '[{"value":"lt12","label_de":"< 12 °C","order_index":0},{"value":"ge12","label_de":"≥ 12 °C","order_index":1}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'polishing_temp_band') AND w.code = 'A262-27' AND s.code = 'DWA-A-262E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'q_F_T_polishing_max', 'Zulässige hydraulische Flächenbelastung q_Fo,T der Nachreinigungsstufe VF Sand (Tab. 15)', 'number', 'l/(m²·d)', false, '§4.3.6.1, Tab. 15', 'Plan 3: Grenzwert aus TABLE15 zum Temperaturband (≤ 80 / ≤ 120); die Redox-Erhöhung der Fußnote *) ist a262e-P-1.', 'imported_unverified', '& $q_{F o, T}$ & $<12^{\circ} \mathrm{C} \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ & $\leq 80$ \\ \hline & $q_{F o, T}$ & $\geq 12^{\circ} \mathrm{C} \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ & $\leq 120^{*}$ \\', 'lookup_fill', '{"source_label":"Tab. 15"}'::jsonb, '{"table_code":"TABLE15","role":"limit","keys":[{"column":"temp_band","from_symbol":"polishing_temp_band"}],"value":"q_f_t_max"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'q_F_T_polishing_max') AND w.code = 'A262-27' AND s.code = 'DWA-A-262E';
